import pandas as pd, numpy as np
BASE="data/v23_golive_audit_2014_now_matpostbull_shrink0_edge_etfliqcustompitg_wtnamecap{tag}.csv"
runs={"control":"_exp_dropnone","ScopeA":"_exp_dropMOMN-MOMS","ScopeB":"_exp_dropMEGA-MOM-MOMN-MOMS"}
def nav(tag):
    df=pd.read_csv(BASE.format(tag=tag),low_memory=False)
    d=df[df["combined_nav"].notna()&df["ymd"].notna()].copy()
    d["ymd"]=pd.to_datetime(d["ymd"],errors="coerce")
    return d.dropna(subset=["ymd"]).sort_values("ymd").groupby("ymd")["combined_nav"].last().astype(float)
N={k:nav(t) for k,t in runs.items()}
def py(n):
    return {y:(g.iloc[-1]/g.iloc[0]-1)*100 for y,g in n.groupby(n.index.year) if len(g)>=5}
P={k:py(n) for k,n in N.items()}
yrs=sorted(P["control"])
print("year   ctrl    ScopeA  dA     ScopeB  dB")
for y in yrs:
    c=P["control"][y]; a=P["ScopeA"].get(y,float('nan')); b=P["ScopeB"].get(y,float('nan'))
    print(f"{y}  {c:+7.2f} {a:+7.2f} {a-c:+6.1f} {b:+7.2f} {b-c:+6.1f}")
# window deltas via daily-return chaining
def full(n,mask=None):
    r=n.pct_change().dropna()
    if mask is not None: r=r[mask(r.index)]
    yr=(r.index[-1]-r.index[0]).days/365.25
    return ((1+r).prod()**(1/yr)-1)*100
for lbl,mask in [("2022+",lambda i:i.year>=2022),("2024+",lambda i:i.year>=2024),
                 ("OOS ex2021",lambda i:(i.year>=2020)&(i.year!=2021))]:
    dA=full(N["ScopeA"],mask)-full(N["control"],mask)
    print(f"{lbl:12} ScopeA {dA:+.2f}pp")
